"""Currículos web autorais: cada módulo tem construção, investigação e verificação."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1] if Path(__file__).parent.name=='scripts' else Path('/workspace/sites/forge-academy-refresh')
def m(title, concept, code, expected, trap, task): return dict(title=title,concept=concept,code=code,expected=expected,trap=trap,task=task)
DATA={
'react': dict(name='React',hours=216,language='jsx',extension='jsx',source='https://react.dev/learn',prerequisites=['JavaScript: funções, arrays, objetos, módulos, eventos e promessas.','HTML semântico, CSS, TypeScript básico e ambiente Vite.'],setup='Crie um laboratório com npm create vite@latest laboratorio -- --template react-ts, siga o requisito de Node indicado pelo Vite e execute npm install. Troque src/App.tsx pelo exemplo. Use npm run dev; os exercícios avançados indicam quando criar arquivos adicionais.',final='Painel de estudos acessível em React',modules=[
m('Componentes e JSX','Componentes são funções puras que descrevem a interface. JSX exige expressões entre chaves e nomes de componentes com inicial maiúscula.','export default function App(){const titulo="Estudos";return <main><h1>{titulo}</h1><p>Uma etapa por vez.</p></main>}', 'A página apresenta um título Estudos dentro de main.','Chamar uma função com efeitos colaterais enquanto o componente renderiza.','Extraia um componente Cabecalho com título recebido por propriedade.'),
m('Props e composição','Props são entradas somente de leitura; children permite compor conteúdo sem duplicar a estrutura.','function Cartao({children}:{children:React.ReactNode}){return <section>{children}</section>}\nexport default function App(){return <Cartao><h2>Revisão</h2></Cartao>}', 'Uma seção contém o título Revisão.','Alterar diretamente um objeto recebido por props.','Faça dois cartões com conteúdos diferentes e a mesma estrutura sem usar uma prop para cada elemento.'),
m('Estado e eventos','Uma atualização de estado agenda uma nova renderização. Use a forma funcional quando o próximo valor depende do anterior.','import {useState} from "react";\nexport default function App(){const [n,setN]=useState(0);return <button onClick={()=>{setN(x=>x+1);setN(x=>x+1)}}>{n}</button>}', 'Cada clique aumenta o número em 2.','Esperar que duas chamadas setN(n+1) acumulem sobre o mesmo snapshot.','Adicione uma operação de reinício e limite o contador a um valor definido pelo contrato.'),
m('Listas, identidade e imutabilidade','Keys estáveis identificam itens entre renderizações. Atualize arrays criando uma coleção nova e preserve os IDs do domínio.','import {useState} from "react";\nexport default function App(){const [itens,setItens]=useState([{id:1,nome:"Go"},{id:2,nome:"React"}]);return <><button onClick={()=>setItens(xs=>xs.filter(x=>x.id!==1))}>Remover Go</button><ul>{itens.map(x=><li key={x.id}>{x.nome}</li>)}</ul></>}', 'Ao remover Go, React continua na lista com sua identidade.','Usar o índice como key em uma lista que permite exclusão e reordenação.','Adicione ordenação por nome sem mutar o array guardado no estado.'),
m('Formulários acessíveis','Um campo controlado recebe value e onChange. Label, mensagens e envio por teclado fazem parte do comportamento do formulário.','import {useState} from "react";\nexport default function App(){const [nome,setNome]=useState("");return <form onSubmit={e=>{e.preventDefault();alert(nome.trim())}}><label htmlFor="nome">Nome</label><input id="nome" value={nome} onChange={e=>setNome(e.target.value)} required/><button>Salvar</button></form>}', 'Enter ou o botão envia o nome sem recarregar a página.','Tratar placeholder como substituto de um label.','Valide espaços em branco e anuncie o erro com uma mensagem associada ao campo.'),
m('Estado derivado e reducer','Calcule dados derivados durante a renderização; reducers concentram transições e precisam ser puros.','import {useReducer} from "react";\nexport default function App(){const [n,dispatch]=useReducer((s:number,a:"mais"|"menos")=>a==="mais"?s+1:Math.max(0,s-1),0);return <><output>{n}</output><button onClick={()=>dispatch("mais")}>Mais</button><button onClick={()=>dispatch("menos")}>Menos</button></>}', 'Menos nunca produz um número negativo.','Guardar o total derivado em outro estado que pode ficar desatualizado.','Modele adicionar, concluir e remover tarefas em um reducer e rejeite IDs ausentes.'),
m('Effects e sincronização','Effects sincronizam com sistemas externos. A limpeza deve desfazer a inscrição; não use effect para copiar valores derivados para outro estado.','import {useEffect,useState} from "react";\nexport default function App(){const [online,setOnline]=useState(navigator.onLine);useEffect(()=>{const update=()=>setOnline(navigator.onLine);addEventListener("online",update);addEventListener("offline",update);return()=>{removeEventListener("online",update);removeEventListener("offline",update)}},[]);return <p>{online?"Online":"Offline"}</p>}', 'Os eventos atualizam o texto; desmontar remove as duas inscrições.','Omitir dependências ou a limpeza para silenciar um problema.','Teste montar, desmontar e montar novamente sem acumular listeners.'),
m('Assincronismo e corrida','Uma resposta antiga não pode substituir a consulta mais recente. Cancele a requisição e represente carregamento, erro, vazio e sucesso explicitamente.','import {useEffect,useState} from "react";\nexport default function App(){const [dados,setDados]=useState("Carregando");useEffect(()=>{const c=new AbortController();fetch("/api/cursos",{signal:c.signal}).then(r=>{if(!r.ok)throw Error("HTTP "+r.status);return r.json()}).then(x=>setDados(JSON.stringify(x))).catch(e=>{if(e.name!=="AbortError")setDados("Falha ao carregar")});return()=>c.abort()},[]);return <p role="status">{dados}</p>}', 'Com uma API local, há estado de carregamento, resposta ou falha; sem API, a falha é visível.','Tratar qualquer resposta HTTP como sucesso antes de consultar ok.','Crie uma API simulada local e provoque uma resposta lenta e outra com erro 500.'),
m('Context e hooks de domínio','Context distribui uma dependência compartilhada; um hook pode encapsular o contrato. Estado de formulário local não precisa virar estado global.','import {createContext,useContext} from "react";\nconst Tema=createContext("claro");\nfunction Leitor(){return <p>{useContext(Tema)}</p>}\nexport default function App(){return <Tema.Provider value="escuro"><Leitor/></Tema.Provider>}', 'Leitor apresenta escuro porque está dentro do provider.','Usar um único contexto para todas as mudanças da aplicação sem medir suas consequências.','Crie useTema e compare o comportamento dentro e fora de seu provider.'),
m('Refs, foco e navegação','Refs preservam acesso ao elemento sem solicitar renderização. Após ações que mudam o contexto, planeje foco e preserve links reais para navegação.','import {useRef} from "react";\nexport default function App(){const campo=useRef<HTMLInputElement>(null);return <><label htmlFor="busca">Buscar</label><input ref={campo} id="busca"/><button onClick={()=>campo.current?.focus()}>Ir para busca</button><a href="#resultado">Resultados</a><section id="resultado">Lista</section></>}', 'O botão move o foco para a busca; o link possui destino real.','Guardar o valor visível apenas em ref e esperar que a interface se atualize.','Adicione um diálogo acessível com retorno de foco e descreva quando um roteador seria necessário.'),
m('Testes e limites de erro','Verifique interações pelo comportamento que o usuário observa. Error boundaries tratam falhas de renderização de descendentes; erros de eventos e requisições exigem tratamento próprio.','import {Component,type ReactNode} from "react";\nclass Limite extends Component<{children:ReactNode},{erro:boolean}>{state={erro:false};static getDerivedStateFromError(){return {erro:true}};render(){return this.state.erro?<p role="alert">Não foi possível abrir esta seção.</p>:this.props.children}}\nexport default function App(){return <Limite><p>Conteúdo estável</p></Limite>}', 'A seção normal aparece; uma falha de renderização descendente pode apresentar o fallback.','Supor que um error boundary captura toda rejeição de fetch ou erro em onClick.','Use Testing Library e um runner configurado para testar nome acessível, envio válido e erro de rede.'),
m('Arquitetura, desempenho e entrega','Separe estado por responsabilidade e meça antes de memorizar. Acessibilidade, testes, observação de falhas e build reproduzível fazem parte da entrega.','import {lazy,Suspense} from "react";\nconst Ajuda=lazy(()=>Promise.resolve({default:()=> <aside>Ajuda carregada</aside>}));\nexport default function App(){return <main><h1>Painel</h1><Suspense fallback={<p>Carregando ajuda</p>}><Ajuda/></Suspense></main>}', 'A ajuda aparece dentro da fronteira Suspense; o exemplo demonstra o protocolo, não economia real de bundle.','Afirmar melhoria de bundle sem usar import dinâmico de um módulo separado e sem medir.','Mova Ajuda para outro arquivo com import dinâmico e compare o bundle e o carregamento no navegador.')]),
 'typescript':dict(name='TypeScript',hours=144,language='typescript',extension='ts',source='https://www.typescriptlang.org/docs/handbook/intro.html',prerequisites=['JavaScript: funções, objetos, arrays, módulos e promessas.'],setup='Em uma pasta local execute npm init -y e npm install --save-dev typescript. Confira a documentação do compilador instalado. Salve exemplo.ts e execute npx tsc exemplo.ts --strict --target ES2022 --module commonjs --outDir saida e node saida/exemplo.js. Exemplos DOM são conferidos no navegador; exemplos de erro devem falhar na checagem.',final='Motor tipado de pedidos e validação de entrada',modules=[
m('Inferência e compilação','TypeScript verifica contratos durante o desenvolvimento; os tipos não validam dados automaticamente em execução.','const horas = 8;\nconst total: number = horas * 4;\nconsole.log(total);','32','Esperar que uma anotação de tipo transforme texto recebido da rede em número.','Introduza uma atribuição incompatível e registre o diagnóstico de tsc.'),
m('Objetos e propriedades opcionais','Modele ausência com propriedade opcional e trate undefined antes de usar o valor.','type Aluno={nome:string;apelido?:string};\nconst a:Aluno={nome:"Alex"};\nconsole.log(a.apelido?.toUpperCase() ?? a.nome);','Alex','Aplicar non-null assertion para esconder uma ausência possível.','Adicione um apelido vazio e defina uma política diferente para vazio e ausente.'),
m('Unions e narrowing','Uma verificação de typeof restringe a união no ramo em que a condição foi comprovada.','function tamanho(x:string|string[]){return typeof x==="string"?x.length:x.length;}\nconsole.log(tamanho("Go"),tamanho(["Go","React"]));','2 2','Converter com as para remover um erro sem comprovar a forma do dado.','Altere o retorno para normalizar texto e arrays de forma diferente.'),
m('Funções e contratos','Parâmetros, retornos e callbacks expressam a transformação permitida. O corpo deve respeitar todas as possibilidades da assinatura.','function aplicar(xs:number[],fn:(n:number)=>number):number[]{return xs.map(fn)}\nconsole.log(aplicar([1,2],n=>n*2));','[ 2, 4 ]','Usar any no callback para aceitar uma transformação incompatível com o retorno.','Crie um callback que retorna string e documente o diagnóstico esperado.'),
m('Uniões discriminadas','Uma propriedade discriminante identifica estados válidos e evita combinações impossíveis de flags.','type Resultado={ok:true;valor:number}|{ok:false;erro:string};\nfunction mostrar(r:Resultado){return r.ok?r.valor.toFixed(2):r.erro}\nconsole.log(mostrar({ok:false,erro:"Entrada inválida"}));','Entrada inválida','Permitir simultaneamente sucesso true e dados de erro obrigatórios sem discriminar os estados.','Adicione estado pendente e faça uma conferência exaustiva com never.'),
m('Generics e relações','Um parâmetro genérico preserva a relação entre entrada e saída sem perder informação para any.','function primeiro<T>(xs:readonly T[]):T|undefined{return xs[0]}\nconsole.log(primeiro(["Go","React"]));','Go','Declarar que primeiro sempre retorna T, mesmo para um array vazio.','Teste uma lista vazia e exija tratamento do undefined no consumidor.'),
m('Keyof e acesso seguro','Keyof restringe chaves ao contrato do objeto; o tipo indexado preserva o tipo da propriedade retornada.','function ler<T,K extends keyof T>(x:T,k:K):T[K]{return x[k]}\nconsole.log(ler({nome:"Alex",horas:8},"horas"));','8','Aceitar qualquer string como chave e afirmar que o valor sempre existe.','Tente uma chave inexistente e compare com uma entrada dinâmica validada em execução.'),
m('Mapped types e utilitários','Readonly, Pick e Partial transformam contratos estáticos; readonly não congela o objeto em execução.','type Curso={id:number;titulo:string};\nconst resumo:Readonly<Pick<Curso,"titulo">>={titulo:"TypeScript"};\nconsole.log(resumo.titulo);','TypeScript','Confundir Readonly com Object.freeze e com congelamento profundo.','Desenhe um patch com campos permitidos sem liberar a alteração do ID.'),
m('Unknown e validação real','Unknown exige prova antes do uso. Valide estrutura, tipo e regra de domínio de cada dado externo.','function positivo(x:unknown):number{if(typeof x!=="number"||!Number.isFinite(x)||x<=0)throw Error("Número positivo exigido");return x}\nconsole.log(positivo(3));','3; a entrada "3" é rejeitada.','Usar JSON.parse seguido de as Pedido como se isso validasse o conteúdo.','Teste zero, NaN, string, null e um valor positivo com resultados esperados.'),
m('Promessas e falhas','Promise descreve o valor resolvido; erros continuam precisando de tratamento em execução.','async function carregar():Promise<number>{return 3}\ncarregar().then(x=>console.log(x)).catch(e=>console.error(String(e)));','3','Supor que Promise<number> impede falhas de rede ou garante o formato do JSON.','Receba unknown de uma função assíncrona e valide antes de retornar um valor de domínio.'),
m('Módulos e configuração estrita','O compilador e o runtime precisam concordar sobre resolução de módulos. Um arquivo com export tem escopo de módulo.','export type Curso={id:number};\nconst curso:Curso={id:1};\nconsole.log(curso.id);','1','Escolher resolução de módulos de bundler e esperar a mesma resolução em todo runtime Node.','Separe o tipo em outro módulo e compile com configuração compatível com a execução escolhida.'),
m('Tipos condicionais e testes de contrato','Tipos condicionais expressam relações, mas não substituem funções de validação nem testes de execução.','type Item<T>=T extends readonly (infer U)[]?U:T;\nconst item:Item<string[]>="React";\nconsole.log(item);','React','Tornar o tipo público tão complexo que o consumidor precisa de assertions para utilizá-lo.','Crie exemplos que devem compilar e falhar com @ts-expect-error; mantenha o contrato simples.')]),
 'vite':dict(name='Vite',hours=72,language='javascript',extension='js',source='https://vite.dev/guide/',prerequisites=['HTML, CSS, JavaScript e módulos ESM.','Terminal, npm e noções de Git. TypeScript básico para o template react-ts.'],setup='Crie um laboratório com npm create vite@latest laboratorio -- --template vanilla. Use uma versão de Node compatível com a versão instalada do Vite, execute npm install e npm run dev. Os exemplos de configuração vão em vite.config.js; os de interface em src/main.js ou index.html, conforme a aula.',final='Catálogo web reproduzível com build e publicação',modules=[
m('Projeto e ciclo de desenvolvimento','Vite fornece servidor de desenvolvimento e build. O entry HTML faz parte do projeto e o lockfile registra dependências resolvidas.','// Terminal\n// npm create vite@latest laboratorio -- --template vanilla\n// cd laboratorio\n// npm install\n// npm run dev\nconsole.log("Confira a URL mostrada no terminal");','O terminal apresenta a URL local e a página abre pelo servidor.','Abrir index.html por file:// e esperar todas as funções do servidor Vite.','Identifique entry HTML, código fonte, manifesto e lockfile no projeto criado.'),
m('ESM e grafo de dependências','Imports estáticos formam o grafo de módulos; caminhos são resolvidos pelo ambiente de build.','// src/main.js\nimport "./style.css";\ndocument.querySelector("#app").textContent="Módulo carregado";','O texto aparece no elemento #app do template vanilla.','Supor que um alias definido no editor também configura o bundler.','Extraia uma função para outro módulo e use import/export explícitos.'),
m('CSS e isolamento','CSS importado entra no grafo do build. CSS Modules permite nomes locais, mas não substitui semântica nem acessibilidade.','// src/main.js\nimport estilos from "./card.module.css";\nconst card=document.createElement("section");card.className=estilos.card;card.textContent="Curso";document.querySelector("#app").replaceChildren(card);\n// Crie src/card.module.css contendo .card { padding: 1rem; }','Um cartão com padding é exibido com classe transformada.','Usar uma classe global esperando que o arquivo .module.css a trate como global automaticamente.','Crie dois cartões em módulos diferentes e prove que seus nomes locais não colidem.'),
m('Assets e caminhos públicos','Assets importados são processados; public mantém nomes estáveis. Configure base para o caminho em que a aplicação realmente será servida.','// src/main.js; adicione public/guia.txt\nconst link=document.createElement("a");link.href=import.meta.env.BASE_URL+"guia.txt";link.textContent="Guia";document.querySelector("#app").replaceChildren(link);','O link aponta para o arquivo público respeitando BASE_URL.','Usar caminhos absolutos de raiz em uma aplicação publicada dentro de subdiretório.','Configure base /academia/ e confira os links no build servido nesse prefixo.'),
m('Variáveis e fronteira de segredos','Valores VITE_ são expostos ao cliente e são strings; não coloque credenciais neles. Valide números e booleanos explicitamente.','// src/main.js\nconst titulo=import.meta.env.VITE_TITULO ?? "Academia";\ndocument.querySelector("#app").textContent=titulo;','Com VITE_TITULO definido antes de iniciar o processo, seu texto aparece; caso contrário, Academia.','Guardar uma senha de banco em VITE_DATABASE_PASSWORD.','Defina uma variável pública em .env.local e mostre que ela pode ser encontrada no código enviado ao navegador.'),
m('Configuração e plugins','A configuração descreve plugins e transformações; cada plugin deve ter uma responsabilidade verificável.','// vite.config.js\nimport {defineConfig} from "vite";\nexport default defineConfig({server:{strictPort:true},build:{sourcemap:false}});','O servidor falha se a porta estiver ocupada em vez de escolher outra silenciosamente.','Adicionar plugins sem medir a necessidade ou conferir compatibilidade com a versão do Vite.','Documente uma configuração necessária ao seu projeto e compare com o comportamento padrão.'),
m('Proxy e contrato HTTP','O proxy do servidor de desenvolvimento não é o backend da produção nem resolve autenticação ou CORS em todos os ambientes.','// vite.config.js\nimport {defineConfig} from "vite";\nexport default defineConfig({server:{proxy:{"/api":"http://localhost:3000"}}});','Com uma API local na porta 3000, /api é encaminhado durante o desenvolvimento.','Concluir que server.proxy será incluído automaticamente no JavaScript de produção.','Simule um erro 500 no backend e documente o encaminhamento e a mensagem mostrada ao usuário.'),
m('Import dinâmico e carregamento','Um import dinâmico de arquivo separado permite criar uma fronteira de carregamento. Verifique o resultado no bundle em vez de presumir divisão.','// src/main.js; crie src/ajuda.js com export default "Guia";\nconst botao=document.createElement("button");botao.textContent="Ajuda";botao.onclick=async()=>{const m=await import("./ajuda.js");botao.textContent=m.default};document.querySelector("#app").replaceChildren(botao);','Ajuda é carregada quando o botão é acionado.','Medir apenas tamanho do fonte, ignorando os arquivos produzidos e a rede.','Compare os arquivos gerados e a rede antes e depois do clique.'),
m('TypeScript e checagem separada','Transpilar sintaxe TypeScript não equivale a verificar os tipos. Execute tsc com noEmit como etapa própria.','// Em projeto configurado com TypeScript:\n// npx tsc --noEmit\n// npm run build\nconsole.log("Checagem de tipos e build são etapas distintas");','Um erro de tipos deve impedir a aprovação da entrega mesmo se a transpilação do bundle funcionar.','Considerar um build concluído como prova de ausência de erros de tipos.','Introduza uma incompatibilidade de tipos e compare o resultado de tsc e do build.'),
m('Testes e modos','Um runner de testes precisa de configuração e ambientes coerentes. O modo de build influencia arquivos de ambiente, mas não cria proteção para segredos.','// Terminal no projeto com testes configurados:\n// npm ci\n// npm test -- --run\n// npm run build -- --mode staging\nconsole.log("Registre a configuração e o resultado de cada etapa");','Testes e build produzem evidências separadas; um modo staging usa sua configuração correspondente.','Assumir que NODE_ENV e mode são a mesma variável em todos os comandos.','Configure Vitest segundo sua documentação e faça um teste falhar antes de comprovar a correção.'),
m('Build, preview e hospedagem','vite preview verifica localmente a saída do build; a publicação exige um servidor ou serviço apropriado para os artefatos.','// Terminal\n// npm run build\n// npm run preview\nconsole.log("Inspecione dist e teste o caminho de publicação");','Os arquivos em dist são servidos pela prévia local.','Usar preview como se fosse um servidor de produção com políticas operacionais prontas.','Teste a saída em um servidor estático e configure fallback apenas se sua navegação realmente precisar.'),
m('SSR, fronteiras e diagnóstico','SSR envolve execução no servidor e no cliente. APIs DOM não existem durante a renderização no servidor e dados privados não devem vazar pela hidratação.','export function titulo(curso){return String(curso.nome)}\nconsole.log(titulo({nome:"React"}));\n// Esta função é pura: não depende de document nem de window.','React; a função pode ser usada em ambientes sem DOM.','Ler document em código executado também no servidor.','Compare uma arquitetura SPA com SSR e documente o que mudaria no entry, nos dados e no processo de hospedagem.')]),
 'html':dict(name='HTML',hours=72,language='html',extension='html',source='https://developer.mozilla.org/en-US/docs/Learn_web_development/Core/Structuring_content',prerequisites=['Saber criar e salvar arquivos em um computador.'],setup='Salve cada exemplo como index.html e abra em um navegador. Use DevTools e navegação por teclado. Para investigar rede e formulários com servidor, use um servidor HTTP local; não envie dados reais nos exercícios.',final='Portal acessível de inscrição em cursos',modules=[
m('Documento e idioma','Doctype, idioma, título e charset definem uma base interpretável pelo navegador e por tecnologias assistivas.','<!doctype html><html lang="pt-BR"><meta charset="utf-8"><title>Academia</title><h1>Aprender</h1></html>','A aba mostra Academia e a página apresenta Aprender.','Tratar título da aba e h1 como o mesmo elemento.','Adicione head e body explícitos e explique o papel de cada metadado.'),
m('Seções e hierarquia','Títulos representam a hierarquia do conteúdo; main identifica o conteúdo principal.','<main><h1>Cursos</h1><section aria-labelledby="web"><h2 id="web">Web</h2><p>HTML e CSS.</p></section></main>','Há um título principal e uma seção Web nomeada.','Escolher níveis de título apenas pelo tamanho visual.','Crie uma segunda seção e percorra a estrutura de títulos nas ferramentas de acessibilidade.'),
m('Links e destinos','Âncoras navegam para destinos; botões executam ações. O texto do link precisa indicar o destino.','<a href="#contato">Ir para contato</a><section id="contato"><h2>Contato</h2></section>','O link leva à seção Contato.','Usar um link href=# como botão sem implementar um comportamento acessível.','Adicione um link de pular para o conteúdo e confira seu foco ao usar o teclado.'),
m('Listas e conteúdo estruturado','Listas ordenadas indicam sequência; listas não ordenadas indicam coleção.','<h1>Inscrição</h1><ol><li>Escolher curso</li><li>Preencher dados</li><li>Conferir</li></ol>','As três etapas aparecem em uma sequência numerada.','Usar elementos de lista apenas para obter uma margem específica.','Compare uma lista de cursos com a sequência de inscrição e escolha a estrutura adequada.'),
m('Imagens e alternativas','O texto alternativo comunica a função de uma imagem significativa; uma imagem decorativa usa alt vazio.','<figure><img src="mapa.png" alt="Entrada pela rua lateral" width="320" height="180"><figcaption>Acesso à sala</figcaption></figure>','Com mapa.png disponível, a imagem tem dimensões reservadas e descrição de sua função.','Repetir o nome do arquivo como alternativa sem descrever sua função.','Classifique uma imagem informativa e outra decorativa e justifique seus atributos alt.'),
m('Formulário e labels','Label associa o nome acessível ao controle. Name define o campo enviado pelo formulário.','<form><label for="nome">Nome</label><input id="nome" name="nome" required><button>Conferir</button></form>','O label foca o controle e o envio vazio é recusado pelo navegador.','Confundir id, name e placeholder.','Adicione nome, curso e botão; confirme os nomes dos campos na requisição de teste.'),
m('Tipos e validação','Tipos como email auxiliam entrada e validação no navegador; regras também precisam ser validadas no servidor.','<form><label for="email">E-mail</label><input id="email" name="email" type="email" required><button>Enviar</button></form>','O navegador recusa um endereço sintaticamente inválido no envio normal.','Confiar na validação HTML como barreira suficiente para o backend.','Teste vazio, endereço inválido e válido; descreva como o servidor validaria os mesmos dados.'),
m('Grupos e instruções','Fieldset e legend nomeiam grupos de controles relacionados. Instruções devem continuar visíveis durante a interação.','<fieldset><legend>Turno</legend><label><input type="radio" name="turno" value="manha">Manhã</label><label><input type="radio" name="turno" value="noite">Noite</label></fieldset>','Só um turno pode ser escolhido porque os rádios compartilham name.','Dar names diferentes e esperar seleção mutuamente exclusiva.','Adicione instruções ao grupo e comprove navegação e seleção pelo teclado.'),
m('Tabelas de dados','Cabeçalhos e caption explicam as relações entre dados; tabela não é uma ferramenta de layout da página.','<table><caption>Agenda</caption><tr><th scope="col">Curso</th><th scope="col">Horas</th></tr><tr><td>HTML</td><td>72</td></tr></table>','Uma tabela Agenda relaciona HTML a 72 horas.','Usar células comuns como cabeçalhos apenas aplicando negrito.','Acrescente outro curso e confira se os cabeçalhos continuam associados corretamente.'),
m('Semântica interativa','Prefira controles nativos para herdar teclado e comportamento; ARIA complementa a semântica quando necessário.','<details><summary>Como estudar?</summary><p>Leia, pratique e confira.</p></details>','O resumo pode abrir e fechar o conteúdo com interação nativa.','Adicionar role=button em uma div e presumir que Enter e espaço passam a funcionar.','Compare details com uma implementação manual e liste os comportamentos que precisam ser recriados.'),
m('Metadados e carregamento','Viewport, título e descrição têm funções distintas; a organização dos recursos afeta carregamento e uso em diferentes telas.','<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Cursos de tecnologia"><title>Catálogo</title><main><h1>Catálogo</h1></main></html>','O documento define viewport e metadados próprios para o catálogo.','Tentar corrigir um layout inacessível proibindo zoom.','Teste zoom de 200% e uma tela estreita, registrando problemas para resolver com CSS.'),
m('Qualidade e contrato de entrega','Validar HTML identifica problemas estruturais, mas a qualidade também exige testes de teclado, conteúdo e fluxo.','<main><h1>Inscrição</h1><form><label for="curso">Curso</label><select id="curso" name="curso"><option>HTML</option><option>React</option></select><button>Inscrever</button></form></main>','É possível selecionar um curso e alcançar o envio pelo teclado.','Declarar acessibilidade comprovada apenas porque o validador não encontrou erros.','Faça uma revisão completa do formulário com teclado, zoom, mensagens e dados de fronteira.')]),
 'git':dict(name='Git e GitHub',hours=72,language='bash',extension='sh',source='https://git-scm.com/book/en/v2',prerequisites=['Terminal básico e uma pasta de laboratório sem arquivos importantes.','Conta GitHub apenas para práticas remotas; nunca compartilhe tokens ou senhas nas respostas.'],setup='Instale Git pelo site oficial. Execute comandos dentro de um repositório de laboratório. Configure nome e e-mail locais de teste, sem copiar credenciais. Exemplos com remoto usam um repositório seu; confirme branch e URL antes de enviar alterações.',final='Entrega colaborativa com histórico, revisão e release',modules=[
m('Repositório e status','Git versiona snapshots do conteúdo rastreado; status distingue arquivos novos, alterados e preparados.','git init laboratorio\ncd laboratorio\ngit status','Um repositório novo é criado e status informa a situação inicial.','Supor que criar um arquivo já o colocou no histórico.','Crie notas.txt e compare status antes e depois de salvar o arquivo.'),
m('Staging e commit','O index representa o próximo snapshot; adicionar e fazer commit são etapas distintas.','git status\ngit add notas.txt\ngit diff --cached\n# Após configurar identidade local:\ngit commit -m "Registra notas iniciais"','A diferença preparada é revisada antes de criar o commit.','Usar git add indiscriminadamente sem conferir os arquivos preparados.','Altere novamente notas.txt após o add e compare as duas diferenças.'),
m('Diff e investigação','Diff mostra mudanças; log mostra o histórico. A leitura deve preceder decisões de recuperação ou integração.','git diff\ngit diff --cached\ngit log --oneline -5','São exibidas diferenças não preparadas, preparadas e os últimos commits, quando existirem.','Confundir ausência de diff no diretório com ausência de mudanças no index.','Relacione cada alteração ao estado correspondente usando um pequeno exemplo reproduzível.'),
m('Branches e trabalho isolado','Uma branch é uma referência móvel para um commit, não uma cópia independente de todos os arquivos.','git switch -c estudo\ngit status\ngit branch --show-current','A branch atual passa a ser estudo.','Esperar que mudanças não commitadas pertençam automaticamente a uma branch.','Crie um commit em estudo e compare as referências antes e depois.'),
m('Integração e conflitos','Merge integra históricos. Um conflito exige compreender as duas intenções e validar o resultado combinado.','git switch main\n# Use o nome real da branch principal do seu laboratório.\ngit merge estudo','As alterações são integradas ou um conflito é sinalizado para resolução.','Apagar marcadores de conflito sem testar o comportamento resultante.','Crie um conflito de texto controlado e documente a decisão para cada parte.'),
m('Remotos e rastreamento','Fetch atualiza referências remotas sem integrar automaticamente o conteúdo na branch atual.','git remote -v\ngit fetch origin\ngit status','Com origin configurado, as referências remotas são atualizadas e o estado local pode ser comparado.','Tratar fetch e merge como a mesma operação.','Compare sua branch com origin/main antes de propor uma integração.'),
m('Push e revisão','Push publica commits para um destino explícito. Revise branch, conteúdo e autorização antes de enviar.','git status\ngit log --oneline -3\ngit push -u origin estudo','Com remoto e permissão corretos, estudo é publicada e ganha rastreamento.','Usar force para contornar qualquer rejeição sem investigar mudanças remotas.','Abra uma revisão no GitHub com problema, comportamento esperado e evidências de verificação.'),
m('Ignore e segredos','Gitignore afeta arquivos não rastreados. Uma credencial já publicada precisa ser revogada, mesmo se o arquivo for removido depois.','git status --ignored\ngit ls-files\n# Adicione .env e node_modules/ ao .gitignore antes de criar esses arquivos.','É possível distinguir arquivos ignorados de conteúdo já rastreado.','Achar que adicionar .env ao ignore remove esse arquivo de commits anteriores.','Use apenas um marcador fictício para comprovar que ignorar não altera o histórico existente.'),
m('Revert e recuperação','Revert cria um novo commit inverso e preserva o histórico compartilhado; a recuperação deve partir de referências conferidas.','git log --oneline -5\n# Escolha um commit do laboratório e use git revert SHA_ESCOLHIDO\ngit status','O histórico fornece o identificador a revisar antes de desfazer uma alteração.','Reescrever a branch compartilhada quando um commit inverso resolveria a necessidade.','Crie e reverta uma alteração pequena; confira que os dois eventos continuam no log.'),
m('Rebase e histórico','Rebase reaplica commits e altera seus identificadores; combine seu uso com a política de colaboração.','git status\ngit log --graph --oneline --all -10\n# Faça práticas de rebase apenas em uma branch local de laboratório.','O grafo mostra o ponto em que as branches divergem.','Reescrever commits já consumidos por outras pessoas sem coordenação.','Compare merge e rebase em branches descartáveis e explique o efeito nos identificadores.'),
m('Tags e releases','Uma tag identifica um ponto do histórico. Release deve apontar para um commit verificado e ter instruções reproduzíveis.','git status\ngit tag -a v0.1.0 -m "Primeira entrega verificada"\ngit show v0.1.0 --stat','Uma tag anotada identifica o commit atual do laboratório.','Afirmar que criar uma tag local a publica automaticamente no GitHub.','Descreva o envio explícito da tag e escreva notas com mudanças, compatibilidade e limitações.'),
m('Colaboração e automação','Revisões, verificações e commits pequenos reduzem o custo de diagnóstico; uma execução verde precisa corresponder ao commit entregue.','git status\ngit rev-parse HEAD\ngit log --oneline -3','O identificador exato da entrega pode ser associado às evidências de verificação.','Usar resultados de testes de outro commit como prova da versão publicada.','Prepare um roteiro de clone limpo, instalação, testes e build e peça a outra pessoa para reproduzi-lo.')])}

def question(text,correct,trap,index=0):
 options=[correct,trap,'O contrato pode ser presumido sem observar o resultado.','A aparência isolada comprova o comportamento e todos os casos de erro.']
 shift=index%4; options=options[shift:]+options[:shift]
 return dict(question=text,options=options,answer=options.index(correct),explanation=correct+' '+ 'Compare o contrato com a entrada e com a evidência observada; '+trap[0].lower()+trap[1:]+' não é uma verificação suficiente.')

def build():
 for cid,spec in DATA.items():
  levels=[];lessons=[]
  for i,mod in enumerate(spec['modules'],1):
   tag=['Fundamentos','Intermediário','Avançado','Especialista'][(i-1)//3]
   qs=[]
   for stage,(suffix,goal) in enumerate([('Construir','Executar o exemplo e explicar o contrato'),('Investigar','Alterar uma condição e diagnosticar o comportamento'),('Verificar','Comprovar o contrato e seus limites com evidências')]):
    lid=(i-1)*3+stage+1
    q=question(f'{mod["title"]}: ao {suffix.lower()} a solução, qual decisão preserva o contrato?',mod['concept'],mod['trap'],lid)
    lessons.append(dict(id=lid,level=i,title=mod['title']+' · '+suffix.lower(),goal=goal+': '+mod['task'],theory=[dict(title='O conceito',text=mod['concept']),dict(title='Leia e execute',text='Prepare o ambiente indicado no curso. Antes de executar, preveja este resultado: '+mod['expected']+' Localize no código a expressão, comando ou elemento responsável. Nos trechos comentados, siga as instruções e crie os arquivos auxiliares antes de conferir.'),dict(title='Investigue o limite',text='Um erro frequente é: '+mod['trap']+' Para investigar este módulo: '+mod['task']+' Registre a entrada, a saída observada e o motivo; uma demonstração isolada não prova todas as combinações.')],code=mod['code'],filename='index.html' if cid=='html' else 'App.tsx' if cid=='react' else 'exemplo.ts' if cid=='typescript' else 'roteiro.sh' if cid=='git' else 'roteiro.js',language=spec['language'],run='Abra o arquivo no navegador.' if cid=='html' else 'npm run dev (consulte os arquivos e comandos indicados no exemplo)' if cid in ['react','vite'] else 'Execute os comandos individualmente na pasta de laboratório.' if cid=='git' else 'npx tsc exemplo.ts --strict --target ES2022 --module commonjs --outDir saida && node saida/exemplo.js',expected=mod['expected'],quiz=q,exercises=[dict(id=1,title='Aplicar a mudança',prompt=mod['task']+(' Explique primeiro sua previsão.' if stage==0 else ' Compare duas entradas e registre os resultados.' if stage==1 else ' Entregue um roteiro para outra pessoa reproduzir.'),hint=mod['concept'],solution='Parta do exemplo, mantenha o contrato de '+mod['title']+' e altere apenas a condição investigada. '+mod['concept'],criteria=['Entrega a mudança solicitada e registra o resultado.','Explica a relação entre a alteração e o comportamento.']),dict(id=2,title='Investigar o contraexemplo',prompt='Crie uma reprodução controlada deste erro: '+mod['trap']+' Registre o resultado, corrija e compare.',hint='Use uma cópia do laboratório; escolha um caso pequeno.',solution='O problema viola este princípio: '+mod['concept']+' Compare a execução antes e depois da correção.',criteria=['Mostra uma reprodução do problema.','Corrige a causa e comprova o resultado, sem apenas esconder o erro.']),dict(id=3,title='Evidência de aceitação',prompt='Defina um caso normal, um caso de fronteira e um caso inválido para '+mod['title']+'. Execute ou inspecione cada um e documente o resultado esperado e observado.',hint='Se a camada não rejeita a entrada, explique qual outra camada é responsável.',solution='O caso normal deve comprovar: '+mod['expected']+' A fronteira e a falha devem expor a limitação discutida na aula. Documente o ambiente e passos concretos.',criteria=['Registra três casos com resultados esperados e observados.','Distingue o que foi comprovado e o que continua fora do teste.'])],source=spec['source'],caution='Execute os exemplos no seu ambiente. Os trechos que dependem de API, arquivos ou configuração adicional indicam essa preparação; a plataforma não executa nem certifica o código.',local=True,hours=spec['hours']/36,minutes=45))
    qs.append(q)
   levels.append(dict(id=i,title=mod['title'],tag=tag,hours=spec['hours']/12,summary=mod['concept'],skills=[mod['title'],'Investigação','Verificação'],project=f'Incremento {i}: {mod["title"]}',deliverables=[mod['task'],'Registro do resultado e de um contraexemplo.','Instruções de reprodução em ambiente limpo.'],rubric=[mod['concept'],'Comprova o comportamento antes e depois da alteração.','Apresenta evidências e limites da verificação.'],challenge=qs))
  c=dict(id=cid,name=spec['name'],title='Forge Academy · '+spec['name'],updated='2026-11-24',hours=spec['hours'],description='Aprenda '+spec['name']+' construindo, investigando e verificando soluções, com fundamentos, aplicações e fronteiras avançadas.',prerequisites=spec['prerequisites'],outcome=spec['final'],extension=spec['extension'],codeLanguage=spec['language'],setup=[dict(title='Preparação do laboratório',text=spec['setup']),dict(title='Como estudar',text='Cada módulo contém três aulas: construir, investigar e verificar. Elas aprofundam o mesmo exemplo com tarefas e evidências diferentes. Não avance apenas por marcar atividades; explique o resultado sem copiar.'),dict(title='Ambiente e versões',text='Confira a documentação oficial e registre as versões instaladas. Não use dados reais, segredos ou repositórios importantes nos exercícios.')],references=[dict(title='Documentação oficial de '+spec['name'],description='Referência dos conceitos e ferramentas usados na trilha.',url=spec['source'])],levels=levels,lessons=lessons)
  (ROOT/'curricula'/f'{cid}.json').write_text(json.dumps(c,ensure_ascii=False,indent=2)+'\n')
  combos=[]
  scenarios=['Una a estrutura, as entradas e a interação inicial em uma entrega pequena.','Evolua a entrega para tratar mudanças e casos de fronteira sem perder os contratos anteriores.','Integre estados de falha, comunicação e recuperação; comprove o comportamento em uma reprodução controlada.','Prepare uma entrega reproduzível, com diagnóstico, revisão e limites de operação documentados.']
  for n in range(4):
   mods=spec['modules'][n*3:n*3+3]; req=[n*9+2,n*9+3,n*9+5,n*9+6,n*9+8,n*9+9];qs=[]
   for j,mod in enumerate(mods):
    q=question(f'No cenário "{scenarios[n]}" você precisa combinar {", ".join(x["title"] for x in mods)}. Para a parte {mod["title"]}, qual decisão conserva o contrato?',mod['concept'],mod['trap'],j+n)
    qs.append(dict(id=f'q{j+1}',prompt=q['question'],options=q['options'],answer=q['answer'],explanation=q['explanation'],reviewLessons=[n*9+j*3+2,n*9+j*3+3]))
   combos.append(dict(id=f'combo-{n+1}',title=f'{spec["name"]}: integração {n+1}',scenario=scenarios[n],requiredLessons=req,skills=[x['title'] for x in mods],questions=qs))
  requirements={
  'react':['Catálogo de estudos com componentes, props e identidade estável dos itens.','Adicionar, editar e concluir atividades com transições previsíveis e atualização imutável.','Formulário acessível com validação, mensagens e navegação por teclado.','Consulta a uma API simulada, exibindo carregamento, vazio, erro e sucesso sem corrida entre respostas.','Organização por responsabilidade, limpeza de efeitos e foco previsível.','Testes das interações, build com Vite e explicação das decisões em TypeScript.'],
  'typescript':['Modelar pedidos e estados com uniões discriminadas.','Validar entradas unknown antes de convertê-las em dados do domínio.','Implementar funções e coleções genéricas preservando a relação entre entrada e saída.','Tratar ausência e erros sem any ou assertions para esconder incompatibilidades.','Separar módulos e documentar a configuração estrita compatível com o runtime.','Entregar testes de execução e exemplos positivos e negativos da checagem de tipos.'],
  'vite':['Organizar catálogo em módulos ESM e CSS com recursos locais.','Configurar caminhos de assets para publicação em subdiretório.','Usar apenas configurações públicas no cliente, sem segredos em VITE_.','Documentar a comunicação com API em desenvolvimento e em produção.','Executar a checagem de tipos e testes separadamente do build.','Comprovar instalação pelo lockfile, build reproduzível e teste do artefato em servidor estático.'],
  'html':['Documento com idioma, metadados e hierarquia de títulos coerente.','Catálogo com seções, listas e links para destinos reais.','Formulário com labels, names, tipos, instruções e validação básica.','Agrupamento de opções e mensagens compreensíveis por teclado.','Imagens com alternativas e tabela de dados com cabeçalhos quando necessários.','Relatório de validação estrutural, navegação por teclado e zoom de 200%.'],
  'git':['Repositório de laboratório com commits pequenos e mensagens que descrevem mudanças.','Branch de funcionalidade integrada por uma revisão documentada.','Conflito controlado resolvido e verificado com evidências.','Ignore configurado e conferência do conteúdo rastreado, usando apenas dados fictícios.','Correção reversível com revert e tag anotada para a entrega conferida.','Instruções de clone, reprodução das verificações e vínculo da evidência ao commit exato.']}[cid]
  finalq=[]
  for j,idx in enumerate([4,8,11]):
   mod=spec['modules'][idx];q=question(f'Na defesa de {spec["final"]}, como você justifica a decisão de {mod["title"]}?',mod['concept'],mod['trap'],j+1)
   finalq.append(dict(id=f'q{j+1}',prompt=q['question'],options=q['options'],answer=q['answer'],explanation=q['explanation'],reviewLessons=[idx*3+2,idx*3+3]))
  a=dict(courseId=cid,combos=combos,finalProject=dict(id='final',title=spec['final'],scenario='Consolide os incrementos dos 12 módulos em uma única entrega verificável, usando dados fictícios e explicando os contratos e limites.',requirements=requirements,deliverables=['Código ou repositório do laboratório completo.','README com ambiente, instalação, execução e decisões.','Evidências dos casos normais, de fronteira e de falha.','Relatório de revisão com limitações e próximos passos.'],rubric=[dict(id=f'r{j+1}',title=f'Critério {j+1}',description=x,reviewLessons=[j*6+3,j*6+6]) for j,x in enumerate(requirements)],acceptance=[dict(title='Fluxo principal',setup='Prepare a entrega em ambiente limpo conforme o README.',input='Execute a operação principal e percorra os seis requisitos.',expected='O comportamento observado corresponde aos requisitos e pode ser reproduzido por outra pessoa.',reviewLessons=[3,9,18]),dict(title='Fronteira e falha',setup='Use uma cópia do laboratório e uma entrada inválida ou condição de erro documentada.',input='Provoque a condição de erro, registre o resultado e aplique a recuperação prevista.',expected='A falha é compreensível, não corrompe o estado válido e o relatório explica a responsabilidade de cada camada.',reviewLessons=[12,21,27]),dict(title='Entrega reproduzível',setup='Comece em nova pasta ou clone limpo, sem caches e sem arquivos privados.',input='Siga os comandos e inspeções do README até a versão final.',expected='Os artefatos e evidências correspondem à versão entregue; nenhuma senha ou dado real foi incluído.',reviewLessons=[30,33,36])],questions=finalq))
  (ROOT/'assessments'/f'{cid}.json').write_text(json.dumps(a,ensure_ascii=False,indent=2)+'\n')
